using System.ComponentModel;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the research agent.");

// --- Notebook (shared state for the note-taking tool) ---
var notebook = new Notebook();

// --- Build the chat client with tool support ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()   // automatically invoke tools in-loop
    .Build();

// --- Register tools ---
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchAsync),
        AIFunctionFactory.Create(FetchWebPageAsync),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ],
};

// --- System prompt ---
var systemPrompt = """
    You are a research agent. Your job is to research a topic the user provides.

    Workflow:
    1. Search the web for relevant information using the web_search tool.
    2. Open promising links with fetch_web_page to read details.
    3. Save important findings as notes using add_note with a descriptive title.
    4. Repeat steps 1-3 as needed to cover the topic thoroughly.
    5. Use get_notes to review everything you have collected.
    6. Provide a final, well-structured summary of your research to the user.

    Always cite your sources. Be thorough but concise.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or      ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input)) continue;
    if (input.Equals("quit", StringComparison.OrdinalIgnoreCase)) break;

    history.Add(new ChatMessage(ChatRole.User, $"Please research the following topic: {input}"));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent may make several tool calls)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, chatOptions);
    history.AddRange(response.Messages);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("═══ Research Summary ═══");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();

    // Show collected notes
    if (notebook.Notes.Count > 0)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"📝 {notebook.Notes.Count} note(s) saved during research.");
        Console.ResetColor();
        Console.WriteLine();
    }

    notebook.Clear();
}

Console.WriteLine("Goodbye!");
return;

// ─── Tool Definitions ───────────────────────────────────────────────

[Description("Search the web for a query and return a list of result titles, snippets, and URLs.")]
static async Task<string> WebSearchAsync(
    [Description("The search query")] string query)
{
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    Console.ResetColor();

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";

    try
    {
        var html = await http.GetStringAsync(url);
        var results = ParseDuckDuckGoResults(html);
        return results.Count == 0
            ? "No results found."
            : JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

[Description("Fetch the text content of a web page given its URL.")]
static async Task<string> FetchWebPageAsync(
    [Description("The full URL to fetch")] string url)
{
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  🌐 Fetching: {url}");
    Console.ResetColor();

    using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(15) };
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var html = await http.GetStringAsync(url);
        var text = StripHtml(html);
        // Truncate to keep token usage reasonable
        const int maxLen = 8_000;
        if (text.Length > maxLen)
            text = text[..maxLen] + "\n\n[...content truncated...]";
        return text;
    }
    catch (Exception ex)
    {
        return $"Failed to fetch page: {ex.Message}";
    }
}

// ─── Helpers ─────────────────────────────────────────────────────────

static List<SearchResult> ParseDuckDuckGoResults(string html)
{
    var results = new List<SearchResult>();
    var linkPattern = new Regex(
        @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase);
    var snippetPattern = new Regex(
        @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase);

    var linkMatches = linkPattern.Matches(html);
    var snippetMatches = snippetPattern.Matches(html);

    for (int i = 0; i < Math.Min(linkMatches.Count, 8); i++)
    {
        var rawUrl = linkMatches[i].Groups[1].Value;
        // DuckDuckGo wraps URLs in a redirect; extract the actual URL
        var uddgMatch = Regex.Match(rawUrl, @"uddg=([^&]+)");
        var finalUrl = uddgMatch.Success
            ? Uri.UnescapeDataString(uddgMatch.Groups[1].Value)
            : rawUrl;

        results.Add(new SearchResult
        {
            Title = StripHtml(linkMatches[i].Groups[2].Value).Trim(),
            Url = finalUrl,
            Snippet = i < snippetMatches.Count
                ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
                : "",
        });
    }

    return results;
}

static string StripHtml(string html)
{
    var text = Regex.Replace(html, @"<script[^>]*>.*?</script>", " ", RegexOptions.Singleline | RegexOptions.IgnoreCase);
    text = Regex.Replace(text, @"<style[^>]*>.*?</style>", " ", RegexOptions.Singleline | RegexOptions.IgnoreCase);
    text = Regex.Replace(text, @"<[^>]+>", " ");
    text = System.Net.WebUtility.HtmlDecode(text);
    text = Regex.Replace(text, @"\s+", " ");
    return text.Trim();
}

