{
    public List<Note> Notes { get; } = [];

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string AddNote(
        [Description("Short descriptive title for the note")] string title,
        [Description("The note content / finding")] string content)
    {
        Notes.Add(new Note(title, content, DateTime.UtcNow));
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
        return $"Note '{title}' saved successfully. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review findings before writing a summary.")]
    public string GetNotes()
    {
        if (Notes.Count == 0) return "No notes saved yet.";
        return JsonSerializer.Serialize(Notes, new JsonSerializerOptions { WriteIndented = true });
    }

    public void Clear() => Notes.Clear();
